/**
 * Abstract base tokenizer with generic input type.
 */
trait BaseTokenizer[A] {
  /**
   * Convert value to token.
   */
  def tokenize(value: A): Token

  /**
   * Lazy tokenization of multiple values.
   */
  def tokenizeBatch(values: Iterable[A]): Iterator[Token] =
    values.iterator.map(tokenize)
}

/**
 * Tokenizer for string and bytes types.
 */
final class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  override def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Left(s)      => s
      case Right(bytes) => new String(bytes, encoding)
    }
    val normalized = normalizer(strValue)
    Token(normalized, TokenType.String)
  }

  /**
   * Convenience method for tokenizing strings directly.
   */
  def tokenizeString(value: String): Token =
    Token(normalizer(value), TokenType.String)

  /**
   * Convenience method for tokenizing bytes directly.
   */
  def tokenizeBytes(value: Array[Byte]): Token =
    Token(normalizer(new String(value, encoding)), TokenType.String)
}

object StringTokenizer {
  def apply(
    encoding: String = "UTF-8",
    normalizer: String => String = identity
  ): StringTokenizer = new StringTokenizer(encoding, normalizer)
}

/**
 * Tokenizer for numeric types with precision handling.
 */
final class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Either[Either[Int, Long], Either[Double, BigDecimal]]] {

  override def tokenize(value: Either[Either[Int, Long], Either[Double, BigDecimal]]): Token = {
    val (strValue, originalType) = value match {
      case Left(Left(i))       => (i.toString, "Int")
      case Left(Right(l))      => (l.toString, "Long")
      case Right(Left(d))      => (formatDouble(d), "Double")
      case Right(Right(bd))    => (formatBigDecimal(bd), "BigDecimal")
    }
    Token(strValue, TokenType.Numeric, Map("original_type" -> originalType))
  }

  private def formatDouble(d: Double): String =
    s"%.${precision}f".format(d)

  private def formatBigDecimal(bd: BigDecimal): String =
    bd.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString()

  /**
   * Convenience methods for direct numeric tokenization.
   */
  def tokenizeInt(value: Int): Token =
    Token(value.toString, TokenType.Numeric, Map("original_type" -> "Int"))

  def tokenizeLong(value: Long): Token =
    Token(value.toString, TokenType.Numeric, Map("original_type" -> "Long"))

  def tokenizeDouble(value: Double): Token =
    Token(formatDouble(value), TokenType.Numeric, Map("original_type" -> "Double"))

  def tokenizeBigDecimal(value: BigDecimal): Token =
    Token(formatBigDecimal(value), TokenType.Numeric, Map("original_type" -> "BigDecimal"))
}

object NumericTokenizer {
  def apply(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
  ): NumericTokenizer = new NumericTokenizer(precision, formatOptions)
}

/**
 * Tokenizer for date/time types.
 */
final class TemporalTokenizer(
  formatStr: Option[String] = None
) extends BaseTokenizer[Either[LocalDateTime, LocalDate]] {

  private val isoFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  override def tokenize(value: Either[LocalDateTime, LocalDate]): Token = {
    val formatted = formatStr match {
      case Some(fmt) =>
        val formatter = DateTimeFormatter.ofPattern(fmt)
        value.fold(_.format(formatter), _.format(formatter))
      case None =>
        value match {
          case Left(dt)  => dt.format(isoFormat)
          case Right(d)  => d.format(dateFormat)
        }
    }
    Token(formatted, TokenType.Temporal)
  }

  /**
   * Convenience methods for direct temporal tokenization.
   */
  def tokenizeDateTime(value: LocalDateTime): Token = tokenize(Left(value))

  def tokenizeDate(value: LocalDate): Token = tokenize(Right(value))
}

object TemporalTokenizer {
  val ISO_FORMAT: String = "yyyy-MM-dd'T'HH:mm:ss"
  val DATE_FORMAT: String = "yyyy-MM-dd"

  def apply(formatStr: Option[String] = None): TemporalTokenizer =
    new TemporalTokenizer(formatStr)
}

// ============================================================================
// Universal Tokenizer with Pattern Matching
// ============================================================================

/**
 * Tokenizer that handles multiple types with pattern matching.
 * Uses Scala's pattern matching instead of Python's isinstance checks.
 */
final class UniversalTokenizer {
  private val stringTokenizer = StringTokenizer()
  private val numericTokenizer = NumericTokenizer()
  private val temporalTokenizer = TemporalTokenizer()

  /**
   * Dispatch to appropriate tokenizer based on runtime type.
   * Uses pattern matching for type-safe dispatch.
   */
  def tokenize(value: Any): Token = value match {
    case null                 => Token("NULL", TokenType.Null)
    case None                 => Token("NULL", TokenType.Null)
    case s: String            => stringTokenizer.tokenizeString(s)
    case bytes: Array[Byte]   => stringTokenizer.tokenizeBytes(bytes)
    case i: Int               => numericTokenizer.tokenizeInt(i)
    case l: Long              => numericTokenizer.tokenizeLong(l)
    case d: Double            => numericTokenizer.tokenizeDouble(d)
    case f: Float             => numericTokenizer.tokenizeDouble(f.toDouble)
    case bd: BigDecimal       => numericTokenizer.tokenizeBigDecimal(bd)
    case bd: java.math.BigDecimal => numericTokenizer.tokenizeBigDecimal(BigDecimal(bd))
    case dt: LocalDateTime    => temporalTokenizer.tokenizeDateTime(dt)
    case d: LocalDate         => temporalTokenizer.tokenizeDate(d)
    case Some(v)              => tokenize(v)
    case _                    => Token(value.toString, TokenType.String, Map("fallback" -> true))
  }
}

object UniversalTokenizer {
  def apply(): UniversalTokenizer = new UniversalTokenizer()
}

