final class TokenFunctor[A](private val _value: A) {
  def map[B](func: A => B): TokenFunctor[B] =
    new TokenFunctor(func(_value))

  def flatMap[B](func: A => TokenFunctor[B]): TokenFunctor[B] =
    func(_value)

  def getOrElse(default: => A): A =
    if (_value != null) _value else default

  def get: A = _value
}

object TokenFunctor {
  def apply[A](value: A): TokenFunctor[A] = new TokenFunctor(value)
}

