/**
 * Fluent builder for creating tokenizers.
 */
final class TokenizerBuilder[A] private (
  private val normalizers: Vector[String => String],
  private val validators: Vector[A => Boolean],
  private val metadata: Map[String, Any]
) {

  def withNormalizer(normalizer: String => String): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers :+ normalizer, validators, metadata)

  def withValidator(validator: A => Boolean): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers, validators :+ validator, metadata)

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers, validators, metadata ++ entries.toMap)

  /**
   * Build the final tokenizer function.
   * Returns Either to handle validation failures in a functional way.
   */
  def build(): A => Either[String, Token] = { (value: A) =>
    val validationError = validators.find(v => !v(value))

    validationError match {
      case Some(_) => Left(s"Validation failed for $value")
      case None =>
        val strValue = normalizers.foldLeft(value.toString) { (acc, normalizer) =>
          normalizer(acc)
        }
        Right(Token(strValue, TokenType.String, metadata))
    }
  }

  /**
   * Build the final tokenizer function that throws on validation failure.
   * For compatibility with Python version behavior.
   */
  def buildUnsafe(): A => Token = { (value: A) =>
    build()(value) match {
      case Right(token) => token
      case Left(error)  => throw new IllegalArgumentException(error)
    }
  }
}

object TokenizerBuilder {
  def apply[A](): TokenizerBuilder[A] =
    new TokenizerBuilder(Vector.empty, Vector.empty, Map.empty)
}

// ============================================================================
// Companion Object with Utility Functions
// ============================================================================

/**
 * Main entry point and utility functions for the tokenizer module.
 */
object Tokenizer {
  private val universalTokenizer = UniversalTokenizer()

  /**
   * Convenience function to tokenize any value.
   */
  def tokenize(value: Any): Token = universalTokenizer.tokenize(value)

  /**
   * Batch tokenize multiple values.
   */
  def tokenizeBatch(values: Iterable[Any]): Iterator[Token] =
    values.iterator.map(tokenize)

  /**
   * Convert a tokenizable value to a token using the type class.
   */
  def toToken[A: Tokenizable](value: A): Token = {
    val tokenStr = Tokenizable[A].toToken(value)
    Token(tokenStr, TokenType.String)
  }
}
